using Microsoft.EntityFrameworkCore;
namespace TheBarcode.Api;
public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
 public DbSet<StaffUser> Staff => Set<StaffUser>(); public DbSet<Product> Products => Set<Product>(); public DbSet<Customer> Customers => Set<Customer>(); public DbSet<Sale> Sales => Set<Sale>(); public DbSet<SaleItem> SaleItems => Set<SaleItem>(); public DbSet<Payment> Payments => Set<Payment>(); public DbSet<BillRevision> BillRevisions => Set<BillRevision>(); public DbSet<StockMovement> StockMovements => Set<StockMovement>(); public DbSet<ProductImportBatch> ProductImportBatches => Set<ProductImportBatch>(); public DbSet<ProductImportLine> ProductImportLines => Set<ProductImportLine>(); public DbSet<Expense> Expenses => Set<Expense>(); public DbSet<ExpensePayment> ExpensePayments => Set<ExpensePayment>(); public DbSet<AuditEvent> AuditEvents => Set<AuditEvent>(); public DbSet<OrganizationProfile> Organizations => Set<OrganizationProfile>(); public DbSet<Branch> Branches => Set<Branch>(); public DbSet<Terminal> Terminals => Set<Terminal>(); public DbSet<ReceiptConfiguration> ReceiptConfigurations => Set<ReceiptConfiguration>(); public DbSet<InsightsConfiguration> InsightsConfigurations => Set<InsightsConfiguration>();
 protected override void OnModelCreating(ModelBuilder b){foreach(var type in b.Model.GetEntityTypes()){type.SetTableName(ToSnake(type.GetTableName()!));foreach(var p in type.GetProperties())p.SetColumnName(ToSnake(p.Name));}b.Entity<Product>().HasIndex(x=>x.Barcode).IsUnique().HasFilter("barcode IS NOT NULL");b.Entity<Sale>().HasIndex(x=>x.DeviceTransactionId).IsUnique();b.Entity<Sale>().HasIndex(x=>x.ReceiptNumber).IsUnique();b.Entity<Terminal>().HasIndex(x=>x.DeviceKey).IsUnique();b.Entity<Branch>().HasIndex(x=>x.Code).IsUnique();b.Entity<Sale>().HasMany(x=>x.Items).WithOne().HasForeignKey(x=>x.SaleId).OnDelete(DeleteBehavior.Cascade);b.Entity<Sale>().HasMany(x=>x.Payments).WithOne().HasForeignKey(x=>x.SaleId).OnDelete(DeleteBehavior.Cascade);b.Entity<Sale>().HasMany(x=>x.Revisions).WithOne().HasForeignKey(x=>x.SaleId).OnDelete(DeleteBehavior.Cascade);b.Entity<ProductImportBatch>().HasMany(x=>x.Lines).WithOne().HasForeignKey(x=>x.ProductImportBatchId).OnDelete(DeleteBehavior.Cascade);foreach(var p in new[]{"CostPrice","SellingPrice","Discount","Total","UnitPrice","UnitCost","Amount","PaidAmount","TaxRate"})foreach(var prop in b.Model.GetEntityTypes().SelectMany(e=>e.GetProperties()).Where(x=>x.Name==p)){prop.SetPrecision(18);prop.SetScale(2);}foreach(var p in new[]{"Stock","MinStock","Quantity","QuantityChange","PackageQuantity","StockChange"})foreach(var prop in b.Model.GetEntityTypes().SelectMany(e=>e.GetProperties()).Where(x=>x.Name==p)){prop.SetPrecision(18);prop.SetScale(3);}}
 static string ToSnake(string value)=>string.Concat(value.Select((c,i)=>char.IsUpper(c)&&i>0?$"_{char.ToLowerInvariant(c)}":char.ToLowerInvariant(c).ToString()));
}
